// Synced from prompts/icp.json and prompts/system-prompt.md by scripts/build-workflow.mjs
function readEnv(name, fallback) {
  try {
    const value = $env[name];
    if (value === undefined || value === null) return fallback;
    const text = String(value).trim();
    return text === '' ? fallback : text;
  } catch (error) {
    return fallback;
  }
}

let envAccess = true;
try {
  void $env;
} catch (error) {
  envAccess = false;
}

const icp = {"name":"B2B teams with a repetitive handoff","offer":"A freelance engagement to connect tools, webhooks, and light AI steps so operators stop retyping the same data.","mustHave":["Sells to other businesses","About 10 to 250 people","More than one system of record, such as a CRM, billing tool, inbox, or spreadsheet","A person can point at a repetitive handoff"],"niceToHave":["A founder or operations lead is the likely buyer","The pain is described in the lead notes, not only implied","UK or European time zones"],"disqualify":["Consumer-only brand","Enterprise procurement as the only way in","No operational task to automate"],"tiers":{"hot":{"minScore":75,"meaning":"Worth a same-week conversation and a CRM record"},"warm":{"minScore":50,"meaning":"Plausible fit, review before outreach"},"cold":{"minScore":0,"meaning":"Log only"}}};
const systemPrompt = "You qualify one B2B lead for a freelance automation and integrations practice.\n\nYou receive an ideal customer profile (ICP), a lead, and text taken from the company website. Decide fit only from those inputs. Do not invent revenue, headcount, funding, or product names. If the input does not support a fact, use \"unknown\".\n\nReturn one JSON object and nothing else. No markdown fences. No commentary before or after the JSON.\n\nThe object must contain exactly these keys:\n- summary: two sentences on what the company appears to do\n- industry: a short label, or \"unknown\"\n- companySize: one of \"1-9\", \"10-49\", \"50-249\", \"250-999\", \"1000+\", \"unknown\"\n- score: an integer from 0 to 100, higher meaning a better fit for the ICP\n- tier: \"hot\", \"warm\", or \"cold\", using the tier thresholds in the ICP\n- reasons: an array of 2 to 4 short strings, each citing the lead or the website text\n- suggestedFirstLine: one sentence the sender can paste as the opening line of an email. Do not invent a personal connection. Do not use the contact's name if it was not provided.\n\nIf the website text is empty, say so inside summary or reasons and score from the lead alone.";
const item = $input.first().json;
const claudeMode = readEnv('CLAUDE_MODE', 'mock').toLowerCase() === 'live' ? 'live' : 'mock';
const crmMode = readEnv('CRM_MODE', 'stub').toLowerCase() === 'hubspot' ? 'hubspot' : 'stub';
const body = item.body !== undefined ? item.body : item;

return [
  {
    json: {
      config: {
        claudeMode,
        claudeModel: readEnv('CLAUDE_MODEL', 'claude-sonnet-5-5'),
        crmMode,
        envAccess,
        maxAttempts: 2,
        icp,
        systemPrompt,
      },
      request: {
        body,
        headers: item.headers || {},
      },
    },
  },
];

const state = $input.first().json;
let payload = state.request ? state.request.body : null;
if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (error) {
    payload = null;
  }
}

const errors = [];
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
  errors.push('Body must be a JSON object with name, email, company, and website.');
  return [{ json: { ...state, valid: false, validationErrors: errors, lead: null, force: null } }];
}

function clean(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/\s+/g, ' ').trim();
}

const name = clean(payload.name);
const email = clean(payload.email).toLowerCase();
const company = clean(payload.company);
let website = clean(payload.website);
const linkedinRaw = clean(payload.linkedinUrl || payload.linkedin || '');
let notes = typeof payload.notes === 'string' ? payload.notes.replace(/\s+/g, ' ').trim() : '';

if (!name) errors.push('name is required.');
if (!email) errors.push('email is required.');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email is not a valid address.');
if (!company) errors.push('company is required.');
function httpUrl(value) {
  let url = value;
  if (!/^https?:\/\//i.test(url)) url = `https://${url}`;
  if (!/^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(url)) return null;
  return url;
}

if (!website) errors.push('website is required.');
else {
  const parsed = httpUrl(website);
  if (!parsed) errors.push('website is not a valid URL.');
  else website = parsed;
}

let linkedinUrl = null;
if (linkedinRaw) {
  const parsed = httpUrl(linkedinRaw);
  if (!parsed) errors.push('linkedinUrl is not a valid URL.');
  else linkedinUrl = parsed;
}

if (notes.length > 4000) notes = notes.slice(0, 4000);
const originalNotes = notes;
let force = null;
if (/\bFORCE_MALFORMED_ONCE\b/.test(originalNotes)) force = 'once';
else if (/\bFORCE_MALFORMED\b/.test(originalNotes)) force = 'malformed';
notes = notes
  .replace(/\bFORCE_MALFORMED_ONCE\b/g, '')
  .replace(/\bFORCE_MALFORMED\b/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const nameParts = name.split(' ').filter(Boolean);
const headers = state.request.headers || {};
const resetHeader = headers['x-reset-store'] || headers['X-Reset-Store'] || '';

return [
  {
    json: {
      ...state,
      valid: errors.length === 0,
      validationErrors: errors,
      force,
      resetStore: String(resetHeader).toLowerCase() === 'true',
      lead: {
        name,
        firstName: nameParts[0] || '',
        lastName: nameParts.slice(1).join(' '),
        email,
        company,
        website,
        linkedinUrl,
        notes,
      },
    },
  },
];

const state = $input.first().json;
return [
  {
    json: {
      ok: false,
      error: 'validation_failed',
      messages: state.validationErrors || ['The lead could not be validated.'],
    },
  },
];

const state = $input.first().json;
