const existing = store.leads[state.lead.email];
if (existing) {
  return [{ json: { ...state, duplicate: true, stored: existing } }];
}
return [{ json: { ...state, duplicate: false } }];

const stored = $input.first().json.stored;
return [
  {
    json: {
      ok: true,
